static int ziirave_wdt_init_duration ( struct i2c_client * client ) { int ret ; if ( ! reset_duration ) { if ( ! client -> dev . of_node ) { ret = - ENODEV ; } else { ret = of_property_read_u32 ( client -> dev . of_node , "reset-duration-ms" , & reset_duration ) ; } if ( ret ) { dev_info ( & client -> dev , "No reset pulse duration specified, using default\n" ) ; return 0 ; } } dev_info ( & client -> dev , "Setting reset duration to %dms" , reset_duration ) ; return i2c_smbus_write_byte_data ( client , ZIIRAVE_WDT_RESET_DURATION , reset_duration ) ; } 